-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 (PickMates) — consolidated installation script
-- ============================================================================
-- Mechanically generated by concatenating, in exact order:
--   supabase/migrations/0001_init.sql  ...  0018_payment_iban_settings.sql
--   supabase/seed.sql
--
-- This file is NOT a source of truth on its own — it is a customer-
-- installation convenience only. The 18 migration files plus seed.sql
-- remain the real, individually-versioned source; if they ever diverge
-- from this file, the migrations are correct and this file is stale and
-- must be regenerated the same way (plain concatenation, nothing
-- hand-edited).
--
-- Usage: Supabase Dashboard > SQL Editor > New Query > paste this whole
-- file > Run. Intended for a completely empty, fresh Supabase project.
-- ============================================================================

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0001_init.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — initial schema
-- ============================================================================
-- Safe to run once against a fresh Supabase project (SQL Editor, or
-- `supabase db push` / `supabase migration up` with the CLI). Every
-- statement is idempotent (IF NOT EXISTS / OR REPLACE / DROP POLICY IF
-- EXISTS) so re-running this file is harmless, but it is NOT written to
-- migrate or preserve data from an existing production schema — review
-- before running against a database that already holds real data.
-- ============================================================================

create extension if not exists pgcrypto;

-- ============================================================================
-- 1. TEAMS
-- ============================================================================
-- id is a readable slug (e.g. 'real-madrid') rather than a uuid: it is the
-- exact value already used throughout the frontend (team <select> options,
-- TeamBadge lookups), so keeping it as the primary key avoids an extra
-- id-translation layer between the UI and the database.
--
-- primary_color / secondary_color back the crest-placeholder badge the UI
-- already renders whenever a real crest image isn't available yet (see
-- `logo`) — an addition beyond the four columns requested, kept so the
-- current approved visual design doesn't regress.
create table if not exists public.teams (
  id              text primary key,
  name            text not null,
  short_name      text not null,
  country         text,
  logo            text,
  primary_color   text not null default '#0B1E3D',
  secondary_color text not null default '#1D4FD7',
  created_at      timestamptz not null default now()
);

-- ============================================================================
-- 2. PLAYERS
-- ============================================================================
-- id is a 1:1 reference to auth.users(id) — there is no password column
-- here on purpose. Authentication (and the password itself) is entirely
-- owned by Supabase Auth; this table only holds the public profile Supabase
-- Auth doesn't: display name, admin flag, cached point total.
create table if not exists public.players (
  id         uuid primary key references auth.users (id) on delete cascade,
  name       text not null,
  is_admin   boolean not null default false,
  points     integer not null default 0,
  created_at timestamptz not null default now()
);

create index if not exists idx_players_points on public.players (points desc);

-- ============================================================================
-- 3. MATCHES
-- ============================================================================
-- Status (UPCOMING / LIVE / FINISHED) is deliberately NOT a stored column.
-- It is fully determined by `start_time` + `finished`, and the frontend
-- already derives it that way (utils/matchState.js) — storing it separately
-- would just be a second source of truth that can drift out of sync with
-- the two real facts. See the `matches_with_status` view below for a
-- server-side equivalent, useful for ad-hoc SQL/reporting.
create table if not exists public.matches (
  id                uuid primary key default gen_random_uuid(),
  home_team_id      text not null references public.teams (id),
  away_team_id      text not null references public.teams (id),
  start_time        timestamptz not null,
  finished          boolean not null default false,
  final_home_score  smallint,
  final_away_score  smallint,
  created_at        timestamptz not null default now(),
  constraint matches_teams_differ check (home_team_id <> away_team_id),
  constraint matches_scores_present_iff_finished check (
    (finished = false and final_home_score is null and final_away_score is null)
    or (finished = true and final_home_score is not null and final_away_score is not null)
  ),
  constraint matches_scores_non_negative check (
    (final_home_score is null or final_home_score >= 0)
    and (final_away_score is null or final_away_score >= 0)
  )
);

create index if not exists idx_matches_start_time on public.matches (start_time);
create index if not exists idx_matches_finished on public.matches (finished);

create or replace view public.matches_with_status as
select
  m.*,
  case
    when m.finished then 'FINISHED'
    when m.start_time <= now() then 'LIVE'
    else 'UPCOMING'
  end as status
from public.matches m;

-- ============================================================================
-- 4. PREDICTIONS
-- ============================================================================
create table if not exists public.predictions (
  id                    uuid primary key default gen_random_uuid(),
  player_id             uuid not null references public.players (id) on delete cascade,
  match_id              uuid not null references public.matches (id) on delete cascade,
  predicted_home_score  smallint not null,
  predicted_away_score  smallint not null,
  points                smallint,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  constraint predictions_unique_per_player_match unique (player_id, match_id),
  constraint predictions_scores_non_negative check (
    predicted_home_score >= 0 and predicted_away_score >= 0
  ),
  constraint predictions_points_valid check (points is null or points in (0, 1, 3))
);

create index if not exists idx_predictions_match on public.predictions (match_id);
create index if not exists idx_predictions_player on public.predictions (player_id);

-- ============================================================================
-- 5. CHAT MESSAGES
-- ============================================================================
-- Global chat — intentionally has no match_id. Player display name is
-- joined from `players` at read time rather than duplicated here.
create table if not exists public.chat_messages (
  id         uuid primary key default gen_random_uuid(),
  player_id  uuid not null references public.players (id) on delete cascade,
  message    text not null check (char_length(btrim(message)) > 0 and char_length(message) <= 1000),
  created_at timestamptz not null default now()
);

create index if not exists idx_chat_messages_created_at on public.chat_messages (created_at);

-- ============================================================================
-- 6. NEW-USER TRIGGER
-- ============================================================================
-- Every Supabase Auth user needs a matching `players` profile row. Rather
-- than trusting the client to create one (which would mean trusting the
-- client with its own is_admin flag), a SECURITY DEFINER trigger creates it
-- server-side the moment the auth user is created. Set the display name
-- (and, for the one admin account, is_admin) via the "User Metadata" JSON
-- when creating the user in the Supabase dashboard — see the setup notes.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.players (id, name, is_admin)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'name', split_part(new.email, '@', 1)),
    coalesce((new.raw_user_meta_data ->> 'is_admin')::boolean, false)
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ============================================================================
-- 7. SCORING — the single source of truth for points, run server-side
-- ============================================================================
-- calculate_points mirrors src/services/scoringService.js#calculatePoints
-- exactly (3 / 1 / 0). Comparing the *sign* of (home - away) is equivalent
-- to comparing HOME/AWAY/DRAW outcome, including the "any draw vs any draw"
-- case: sign(0) = 0 for every draw, predicted or actual.
create or replace function public.calculate_points(
  p_predicted_home smallint,
  p_predicted_away smallint,
  p_final_home smallint,
  p_final_away smallint
)
returns smallint
language sql
immutable
as $$
  select case
    when p_predicted_home = p_final_home and p_predicted_away = p_final_away then 3
    when sign(p_predicted_home - p_predicted_away) = sign(p_final_home - p_final_away) then 1
    else 0
  end::smallint
$$;

-- finish_match: the ONLY way `finished`, `final_home_score`,
-- `final_away_score` and `predictions.points` ever change. SECURITY DEFINER
-- so it can write those (grant-restricted, see section 9) columns on the
-- caller's behalf — but only after re-checking admin status itself, so
-- calling it is never enough on its own; you also have to *be* an admin.
create or replace function public.finish_match(
  p_match_id uuid,
  p_final_home_score smallint,
  p_final_away_score smallint
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže ukončiť zápas.' using errcode = '42501';
  end if;

  if p_final_home_score is null or p_final_away_score is null
     or p_final_home_score < 0 or p_final_away_score < 0 then
    raise exception 'Neplatný výsledok zápasu.' using errcode = '22023';
  end if;

  update public.matches
  set finished = true,
      final_home_score = p_final_home_score,
      final_away_score = p_final_away_score
  where id = p_match_id;

  if not found then
    raise exception 'Zápas sa nenašiel.' using errcode = 'P0002';
  end if;

  update public.predictions
  set points = public.calculate_points(
        predicted_home_score, predicted_away_score, p_final_home_score, p_final_away_score
      ),
      updated_at = now()
  where match_id = p_match_id;

  update public.players pl
  set points = coalesce((
    select sum(pr.points) from public.predictions pr
    where pr.player_id = pl.id and pr.points is not null
  ), 0)
  where pl.id in (select player_id from public.predictions where match_id = p_match_id);
end;
$$;

revoke all on function public.finish_match(uuid, smallint, smallint) from public;
grant execute on function public.finish_match(uuid, smallint, smallint) to authenticated;

-- recalculate_all_points: admin-only maintenance utility (surfaced in the
-- Admin > Nastavenia screen) — re-derives every finished match's points and
-- every player's total from scratch. Useful after correcting a final score
-- via edit; never increments anything, always recomputes.
create or replace function public.recalculate_all_points()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže prepočítať body.' using errcode = '42501';
  end if;

  update public.predictions p
  set points = public.calculate_points(
        p.predicted_home_score, p.predicted_away_score, m.final_home_score, m.final_away_score
      ),
      updated_at = now()
  from public.matches m
  where p.match_id = m.id and m.finished = true;

  update public.predictions p
  set points = null
  from public.matches m
  where p.match_id = m.id and m.finished = false and p.points is not null;

  update public.players pl
  set points = coalesce((
    select sum(pr.points) from public.predictions pr
    where pr.player_id = pl.id and pr.points is not null
  ), 0);
end;
$$;

revoke all on function public.recalculate_all_points() from public;
grant execute on function public.recalculate_all_points() to authenticated;

-- ============================================================================
-- 8. ROW LEVEL SECURITY
-- ============================================================================
alter table public.teams enable row level security;
alter table public.players enable row level security;
alter table public.matches enable row level security;
alter table public.predictions enable row level security;
alter table public.chat_messages enable row level security;

-- ---- teams: read-only for logged-in users; writes are seed/admin-SQL only.
drop policy if exists teams_select on public.teams;
create policy teams_select on public.teams for select to authenticated using (true);

-- ---- players: everyone can read the public leaderboard/profile columns.
-- No insert/update/delete policy exists for `authenticated` at all, so
-- points/is_admin/name can never be changed by a client request — points
-- only move via finish_match / recalculate_all_points (SECURITY DEFINER,
-- bypasses RLS), and is_admin/name only via the dashboard or direct SQL.
drop policy if exists players_select on public.players;
create policy players_select on public.players for select to authenticated using (true);

-- ---- matches: everyone can read; only admins can write. `finished`,
-- `final_home_score`, `final_away_score` are excluded from the column grant
-- below on purpose — even an admin cannot set them directly, only through
-- finish_match().
drop policy if exists matches_select on public.matches;
create policy matches_select on public.matches for select to authenticated using (true);

drop policy if exists matches_admin_insert on public.matches;
create policy matches_admin_insert on public.matches for insert to authenticated
  with check (exists (select 1 from public.players where id = auth.uid() and is_admin));

drop policy if exists matches_admin_update on public.matches;
create policy matches_admin_update on public.matches for update to authenticated
  using (exists (select 1 from public.players where id = auth.uid() and is_admin))
  with check (exists (select 1 from public.players where id = auth.uid() and is_admin));

drop policy if exists matches_admin_delete on public.matches;
create policy matches_admin_delete on public.matches for delete to authenticated
  using (exists (select 1 from public.players where id = auth.uid() and is_admin));

-- ---- predictions: visible to everyone (Live/History/Admin all show every
-- player's tips), but a player can only create/edit their OWN prediction,
-- and only while the match hasn't kicked off yet. This is enforced here —
-- not just by disabling the input in the UI — so it holds even against a
-- modified/malicious client.
drop policy if exists predictions_select on public.predictions;
create policy predictions_select on public.predictions for select to authenticated using (true);

drop policy if exists predictions_insert_own on public.predictions;
create policy predictions_insert_own on public.predictions for insert to authenticated
  with check (
    player_id = auth.uid()
    and exists (
      select 1 from public.matches m
      where m.id = match_id and m.finished = false and m.start_time > now()
    )
  );

drop policy if exists predictions_update_own on public.predictions;
create policy predictions_update_own on public.predictions for update to authenticated
  using (player_id = auth.uid())
  with check (
    player_id = auth.uid()
    and exists (
      select 1 from public.matches m
      where m.id = match_id and m.finished = false and m.start_time > now()
    )
  );

-- ---- chat_messages: everyone can read; a player can only post as themselves.
drop policy if exists chat_select on public.chat_messages;
create policy chat_select on public.chat_messages for select to authenticated using (true);

drop policy if exists chat_insert_own on public.chat_messages;
create policy chat_insert_own on public.chat_messages for insert to authenticated
  with check (player_id = auth.uid());

-- ============================================================================
-- 9. TABLE / COLUMN GRANTS
-- ============================================================================
-- RLS decides WHICH ROWS; these grants decide WHICH COLUMNS. In particular:
-- authenticated users get no write grant at all on players (points/is_admin
-- untouchable by clients), no write grant on predictions.points, and no
-- write grant on matches.finished/final_home_score/final_away_score.
grant usage on schema public to authenticated;

grant select on public.teams to authenticated;
grant select on public.players to authenticated;

grant select on public.matches to authenticated;
grant insert (home_team_id, away_team_id, start_time) on public.matches to authenticated;
grant update (home_team_id, away_team_id, start_time) on public.matches to authenticated;
grant delete on public.matches to authenticated;

-- Both INSERT and UPDATE grant the same value columns (including the
-- conflict-target player_id/match_id): the client's save() does a single
-- upsert(), and PostgREST's merge-duplicates resolution re-applies every
-- payload column — including unchanged conflict-key columns — in the DO
-- UPDATE SET clause, not just the "changed" ones. `points` is excluded from
-- both lists (the client payload never includes it either way), and the
-- predictions_update_own / predictions_insert_own RLS policies above are
-- the actual security boundary for player_id, not these column grants — a
-- user still cannot write a row with someone else's player_id because
-- WITH CHECK rejects it regardless of what columns are grantable.
grant select on public.predictions to authenticated;
grant insert (player_id, match_id, predicted_home_score, predicted_away_score, updated_at) on public.predictions to authenticated;
grant update (player_id, match_id, predicted_home_score, predicted_away_score, updated_at) on public.predictions to authenticated;

grant select on public.chat_messages to authenticated;
grant insert (player_id, message) on public.chat_messages to authenticated;

-- ============================================================================
-- 10. REALTIME
-- ============================================================================
-- Chat is the one feature that explicitly asked for live updates. Matches /
-- predictions realtime can be added the same way later if wanted.
-- (ALTER PUBLICATION ... ADD TABLE errors if the table is already a member,
-- so this is guarded to keep the whole migration safely re-runnable.)
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'chat_messages'
  ) then
    alter publication supabase_realtime add table public.chat_messages;
  end if;
end $$;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0002_prediction_change_limit.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — prediction two-save limit
-- ============================================================================
-- Each player may save/change their prediction for a given match at most
-- TWICE (1 initial save + 1 change). Enforced by a BEFORE UPDATE trigger —
-- not just RLS, not just the frontend — so a third attempt is rejected by
-- Postgres itself regardless of how it's sent (refresh, another browser,
-- devtools, a raw REST call). Reuses the existing `predictions` row per
-- player+match rather than a new table: one extra counter column is enough.
--
-- IMPORTANT: finish_match() and recalculate_all_points() (see 0001) also
-- UPDATE predictions.points for every prediction on a match — that is
-- scoring, not a player edit, and must never be constrained by (or consume)
-- the two-save limit. Both are redefined here to flag that transaction so
-- the trigger below can tell the two apart.
--
-- Idempotent / safe to re-run.
-- ============================================================================

alter table public.predictions
  add column if not exists save_count smallint not null default 1;

alter table public.predictions
  drop constraint if exists predictions_save_count_valid;
alter table public.predictions
  add constraint predictions_save_count_valid check (save_count between 1 and 2);

-- The trigger — not the client — decides the new save_count, so no column
-- grant for it is needed at all (a trigger can set any column of NEW
-- regardless of what the invoking UPDATE's own column privileges are).
-- This runs in addition to, not instead of, the existing
-- predictions_update_own RLS policy (still enforcing "own row" + "before
-- kickoff"): both must pass for a player-initiated update to succeed.
create or replace function public.enforce_prediction_change_limit()
returns trigger
language plpgsql
as $$
begin
  -- Set (transaction-locally) by finish_match() / recalculate_all_points()
  -- right before they bulk-update `points` — that is server-side scoring,
  -- not a player save, and must pass through untouched. A normal
  -- player-initiated upsert never sets this, so the limit still applies.
  if coalesce(current_setting('app.bypass_prediction_limit', true), 'false') = 'true' then
    return NEW;
  end if;

  if OLD.save_count >= 2 then
    raise exception 'Tip je uzamknutý — vyčerpali ste obe možnosti zmeny.' using errcode = '42501';
  end if;
  NEW.save_count := OLD.save_count + 1;
  NEW.updated_at := now();
  return NEW;
end;
$$;

drop trigger if exists trg_prediction_change_limit on public.predictions;
create trigger trg_prediction_change_limit
  before update on public.predictions
  for each row execute function public.enforce_prediction_change_limit();

-- ----------------------------------------------------------------------------
-- Redefine finish_match() / recalculate_all_points() to set the bypass flag
-- before their bulk predictions.points update. Bodies are otherwise
-- unchanged from 0001_init.sql; grants (already applied there) are
-- untouched by CREATE OR REPLACE as long as the signature stays the same.
-- ----------------------------------------------------------------------------
create or replace function public.finish_match(
  p_match_id uuid,
  p_final_home_score smallint,
  p_final_away_score smallint
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže ukončiť zápas.' using errcode = '42501';
  end if;

  if p_final_home_score is null or p_final_away_score is null
     or p_final_home_score < 0 or p_final_away_score < 0 then
    raise exception 'Neplatný výsledok zápasu.' using errcode = '22023';
  end if;

  update public.matches
  set finished = true,
      final_home_score = p_final_home_score,
      final_away_score = p_final_away_score
  where id = p_match_id;

  if not found then
    raise exception 'Zápas sa nenašiel.' using errcode = 'P0002';
  end if;

  perform set_config('app.bypass_prediction_limit', 'true', true);

  update public.predictions
  set points = public.calculate_points(
        predicted_home_score, predicted_away_score, p_final_home_score, p_final_away_score
      ),
      updated_at = now()
  where match_id = p_match_id;

  update public.players pl
  set points = coalesce((
    select sum(pr.points) from public.predictions pr
    where pr.player_id = pl.id and pr.points is not null
  ), 0)
  where pl.id in (select player_id from public.predictions where match_id = p_match_id);
end;
$$;

create or replace function public.recalculate_all_points()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže prepočítať body.' using errcode = '42501';
  end if;

  perform set_config('app.bypass_prediction_limit', 'true', true);

  update public.predictions p
  set points = public.calculate_points(
        p.predicted_home_score, p.predicted_away_score, m.final_home_score, m.final_away_score
      ),
      updated_at = now()
  from public.matches m
  where p.match_id = m.id and m.finished = true;

  update public.predictions p
  set points = null
  from public.matches m
  where p.match_id = m.id and m.finished = false and p.points is not null;

  update public.players pl
  set points = coalesce((
    select sum(pr.points) from public.predictions pr
    where pr.player_id = pl.id and pr.points is not null
  ), 0);
end;
$$;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0003_profile_photos.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — profile photos
-- ============================================================================
-- Adds an avatar to each player, backed by Supabase Storage (never
-- base64/binary in the database — `players.avatar_url` is just a public
-- URL string). A player can only ever write to their own folder in the
-- bucket, and can only ever update their own `avatar_url` row — both
-- enforced server-side (Storage RLS + a narrow, avatar_url-only column
-- grant on `players`), not just by hiding the upload button in the UI.
--
-- Idempotent / safe to re-run.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. players.avatar_url
-- ----------------------------------------------------------------------------
alter table public.players
  add column if not exists avatar_url text;

-- players previously had NO update policy/grant at all for `authenticated`
-- (points/is_admin/name are intentionally client-immutable). This adds
-- exactly one narrow exception: a player may update their OWN avatar_url,
-- nothing else — points/is_admin/name remain just as untouchable as before.
drop policy if exists players_update_own_avatar on public.players;
create policy players_update_own_avatar on public.players for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

grant update (avatar_url) on public.players to authenticated;

-- ----------------------------------------------------------------------------
-- 2. Storage bucket
-- ----------------------------------------------------------------------------
-- Public bucket (so avatars load as plain <img src> everywhere — Podium,
-- ranking, chat — without signed URLs), but WRITES are still fully
-- RLS-gated below. file_size_limit / allowed_mime_types are enforced by
-- Storage itself, server-side — not just by the frontend's own file-picker
-- `accept` attribute and pre-upload size check.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'profile-photos',
  'profile-photos',
  true,
  5242880, -- 5 MB
  array['image/jpeg', 'image/jpg', 'image/png', 'image/webp']
)
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- ----------------------------------------------------------------------------
-- 3. Storage RLS — a player may only write inside their own `{user_id}/...`
-- folder, determined from their auth token, never from anything the client
-- sends. Reads are open to any authenticated user (everyone needs to see
-- everyone else's avatar in the ranking/podium/chat); the bucket being
-- public additionally lets the plain <img> tags load without an auth
-- header at all.
-- ----------------------------------------------------------------------------
drop policy if exists profile_photos_select on storage.objects;
create policy profile_photos_select on storage.objects for select to authenticated
  using (bucket_id = 'profile-photos');

drop policy if exists profile_photos_insert_own on storage.objects;
create policy profile_photos_insert_own on storage.objects for insert to authenticated
  with check (
    bucket_id = 'profile-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists profile_photos_update_own on storage.objects;
create policy profile_photos_update_own on storage.objects for update to authenticated
  using (
    bucket_id = 'profile-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  )
  with check (
    bucket_id = 'profile-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists profile_photos_delete_own on storage.objects;
create policy profile_photos_delete_own on storage.objects for delete to authenticated
  using (
    bucket_id = 'profile-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0004_payments_and_prizes.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — payment-gated access + prize fund (Banka)
-- ============================================================================
-- Adds:
--   1. players.is_paid / payment_amount / paid_at — a player only gets
--      access once Admin marks them paid.
--   2. public.settings — one singleton row holding the 1st/2nd/3rd place
--      prize amounts (single source of truth, admin-editable).
--   3. public.has_access() — the ONE place "does this caller get to use the
--      app" is decided, reused by every table's RLS so access is enforced
--      by Postgres itself, not just by hiding screens in the frontend.
--
-- IMPORTANT — this app already has real players actively using it. Adding
-- `is_paid` with a `false` default would otherwise instantly lock every
-- existing player out the moment this runs. To avoid that destructive
-- side effect, every player who already exists at migration time is
-- backfilled to `is_paid = true` (grandfathered in) — the `false` default
-- only applies to players created from here on, matching "a new player
-- starts unpaid". Review this and adjust the backfill if you'd rather every
-- current player be re-confirmed manually.
--
-- Idempotent / safe to re-run.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. players — payment fields
-- ----------------------------------------------------------------------------
alter table public.players
  add column if not exists is_paid boolean not null default false,
  add column if not exists payment_amount numeric(10, 2) not null default 20,
  add column if not exists paid_at timestamptz;

alter table public.players
  drop constraint if exists players_payment_amount_non_negative;
alter table public.players
  add constraint players_payment_amount_non_negative check (payment_amount >= 0);

-- Grandfather in everyone who already exists (see note above) — new players
-- created after this point still get the `false` default.
update public.players set is_paid = true, paid_at = coalesce(paid_at, now()) where is_paid = false;

-- Admin may update any player's payment fields (never points/is_admin/name —
-- those stay exactly as locked down as before). A player still cannot touch
-- their own payment fields at all — no self-service "mark myself as paid".
drop policy if exists players_admin_update_payment on public.players;
create policy players_admin_update_payment on public.players for update to authenticated
  using (exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin))
  with check (exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin));

grant update (is_paid, payment_amount, paid_at) on public.players to authenticated;

-- IMPORTANT: the grant above and the RLS policy above are not, on their
-- own, enough. `players` already has a SEPARATE permissive UPDATE policy
-- from migration 0003 (`players_update_own_avatar`, using/with check just
-- `id = auth.uid()`, for the avatar feature) — and Postgres combines
-- multiple permissive policies for the same command with OR. That policy
-- has no idea which columns a given UPDATE touches, so a normal player's
-- own "update my row" request would satisfy it regardless of whether
-- is_paid/payment_amount/paid_at are among the changed columns — RLS row
-- checks alone can't express "this row, but only some columns". A BEFORE
-- UPDATE trigger closes that gap the same way the prediction save-limit
-- does: it explicitly rejects any change to these three columns unless the
-- caller is an admin, regardless of which policy let the statement through.
create or replace function public.enforce_player_self_update_restrictions()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_is_admin boolean;
begin
  -- auth.uid() is NULL outside an authenticated PostgREST request (a
  -- migration script, or the project owner running SQL directly in the
  -- dashboard as the postgres role) — that's already a strictly higher
  -- trust level than anything the app's own API surface can reach, so it's
  -- intentionally left unrestricted here. Every request the app's own
  -- client can make always carries a real auth.uid(), so this only ever
  -- exempts direct database access, never a regular player's request.
  if auth.uid() is null then
    return NEW;
  end if;

  select is_admin into v_is_admin from public.players where id = auth.uid();

  if not coalesce(v_is_admin, false) then
    if NEW.is_paid is distinct from OLD.is_paid
       or NEW.payment_amount is distinct from OLD.payment_amount
       or NEW.paid_at is distinct from OLD.paid_at then
      raise exception 'Iba administrátor môže zmeniť stav platby.' using errcode = '42501';
    end if;
  end if;

  return NEW;
end;
$$;

drop trigger if exists trg_player_self_update_restrictions on public.players;
create trigger trg_player_self_update_restrictions
  before update on public.players
  for each row execute function public.enforce_player_self_update_restrictions();

-- ----------------------------------------------------------------------------
-- 2. has_access() — reused by every table's RLS below. Defined here, before
-- anything references it: CREATE POLICY resolves the functions its
-- expression calls immediately (unlike a plpgsql body), so every policy
-- below needs this to already exist.
-- ----------------------------------------------------------------------------
-- SECURITY DEFINER so it can read `players` regardless of the caller's own
-- row-visibility (avoids any RLS-recursion subtlety from being called
-- inside other tables' policies), but it only ever answers a yes/no
-- question about the CALLER's own paid/admin status — it exposes nothing.
create or replace function public.has_access()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.players
    where id = auth.uid() and (is_paid or is_admin)
  );
$$;

-- ----------------------------------------------------------------------------
-- 3. settings — singleton row for the prize fund distribution
-- ----------------------------------------------------------------------------
create table if not exists public.settings (
  id                    boolean primary key default true,
  first_place_prize     numeric(10, 2) not null default 0,
  second_place_prize    numeric(10, 2) not null default 0,
  third_place_prize     numeric(10, 2) not null default 0,
  updated_at            timestamptz not null default now(),
  constraint settings_singleton check (id),
  constraint settings_prizes_non_negative check (
    first_place_prize >= 0 and second_place_prize >= 0 and third_place_prize >= 0
  )
);

insert into public.settings (id) values (true) on conflict (id) do nothing;

alter table public.settings enable row level security;

drop policy if exists settings_select on public.settings;
create policy settings_select on public.settings for select to authenticated
  using (public.has_access());

drop policy if exists settings_admin_update on public.settings;
create policy settings_admin_update on public.settings for update to authenticated
  using (exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin))
  with check (exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin));

grant select on public.settings to authenticated;
grant update (first_place_prize, second_place_prize, third_place_prize, updated_at) on public.settings to authenticated;

-- ----------------------------------------------------------------------------
-- 4. RLS — every existing "any authenticated user" read/write now also
-- requires has_access(). This is the actual enforcement: an unpaid player's
-- Supabase session can authenticate (valid email/password), but every
-- query against real app data is rejected by Postgres itself — not just by
-- the frontend choosing not to render a page.
-- ----------------------------------------------------------------------------
drop policy if exists teams_select on public.teams;
create policy teams_select on public.teams for select to authenticated
  using (public.has_access());

-- A player can always read their OWN row (needed to even determine "am I
-- paid yet" and show the right screen) — everyone else's rows only become
-- visible once the caller themselves has access.
drop policy if exists players_select on public.players;
create policy players_select on public.players for select to authenticated
  using (id = auth.uid() or public.has_access());

drop policy if exists matches_select on public.matches;
create policy matches_select on public.matches for select to authenticated
  using (public.has_access());

drop policy if exists predictions_select on public.predictions;
create policy predictions_select on public.predictions for select to authenticated
  using (public.has_access());

drop policy if exists predictions_insert_own on public.predictions;
create policy predictions_insert_own on public.predictions for insert to authenticated
  with check (
    public.has_access()
    and player_id = auth.uid()
    and exists (
      select 1 from public.matches m
      where m.id = match_id and m.finished = false and m.start_time > now()
    )
  );

drop policy if exists predictions_update_own on public.predictions;
create policy predictions_update_own on public.predictions for update to authenticated
  using (player_id = auth.uid())
  with check (
    public.has_access()
    and player_id = auth.uid()
    and exists (
      select 1 from public.matches m
      where m.id = match_id and m.finished = false and m.start_time > now()
    )
  );

drop policy if exists chat_select on public.chat_messages;
create policy chat_select on public.chat_messages for select to authenticated
  using (public.has_access());

drop policy if exists chat_insert_own on public.chat_messages;
create policy chat_insert_own on public.chat_messages for insert to authenticated
  with check (public.has_access() and player_id = auth.uid());

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0005_admin_player_management.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — admin player creation + league reset
-- ============================================================================
-- Two pieces:
--   1. A case-insensitive unique constraint on players.name, so "Ivan" and
--      "ivan" can't both exist — enforced here as the authoritative check;
--      the admin-create-player Edge Function also pre-checks for a fast,
--      friendly error, but this is what actually prevents a race.
--   2. reset_league_data() — a SECURITY DEFINER RPC, same pattern as
--      finish_match()/recalculate_all_points() (0001/0002): re-checks admin
--      status itself, so calling it is never enough on its own, you also
--      have to *be* an admin. This does everything a plain SQL function
--      safely can. It deliberately does NOT delete player accounts —
--      removing an actual Supabase Auth user requires the Admin API
--      (service_role), which no Postgres function can safely do; that part
--      is handled by the admin-reset-league Edge Function, which calls
--      this RPC first and then deletes each non-admin auth user.
--
-- Idempotent / safe to re-run.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Case-insensitive unique player names
-- ----------------------------------------------------------------------------
drop index if exists players_name_unique_ci;
create unique index players_name_unique_ci on public.players (lower(name));

-- ----------------------------------------------------------------------------
-- 2. reset_league_data() — wipes everything league-specific except player
-- accounts themselves and non-league config (teams).
-- ----------------------------------------------------------------------------
create or replace function public.reset_league_data()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže resetovať ligu.' using errcode = '42501';
  end if;

  -- Children before parents, even though the FKs already cascade this —
  -- explicit and auditable rather than relied-upon-implicitly.
  delete from public.chat_messages;
  delete from public.predictions;
  delete from public.matches;

  -- Whoever remains after the Edge Function removes non-admin accounts
  -- (i.e. the admin) starts from a clean slate too — points are a cache
  -- derived from predictions, which no longer exist.
  update public.players set points = 0;

  -- Prize distribution is league-specific, not app-wide config.
  update public.settings
  set first_place_prize = 0,
      second_place_prize = 0,
      third_place_prize = 0,
      updated_at = now();
end;
$$;

revoke all on function public.reset_league_data() from public;
grant execute on function public.reset_league_data() to authenticated;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0006_fix_reset_league_where_clause.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — fix reset_league_data() "requires a WHERE
-- clause" failure
-- ============================================================================
-- Production error from the admin-reset-league Edge Function's logs:
--   { message: "DELETE requires a WHERE clause", code: "21000" }
--
-- Root cause: Supabase enables the `safeupdate` extension on every project
-- by default, which rejects any bare UPDATE/DELETE with no WHERE clause —
-- exactly to stop an accidental full-table wipe. reset_league_data() (see
-- 0005) has 3 DELETEs and 2 UPDATEs with no WHERE clause at all, so the
-- very first statement (`delete from chat_messages;`) always raised this
-- error before anything else ran. Because the whole function body executes
-- as one statement-level transaction, that failure already rolled back
-- cleanly on its own — nothing was ever partially wiped by this bug.
--
-- Fix: add `where true` to each statement. `safeupdate` only checks for the
-- syntactic presence of a WHERE clause, not what it restricts, so `where
-- true` deletes/updates every row exactly as before — behavior is
-- unchanged, only now it's valid under `safeupdate`.
--
-- Idempotent / safe to re-run.
-- ============================================================================

create or replace function public.reset_league_data()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže resetovať ligu.' using errcode = '42501';
  end if;

  -- Children before parents, even though the FKs already cascade this —
  -- explicit and auditable rather than relied-upon-implicitly.
  -- `where true` is required by Supabase's `safeupdate` extension, which
  -- rejects a bare DELETE/UPDATE with no WHERE clause; it does not change
  -- which rows are affected.
  delete from public.chat_messages where true;
  delete from public.predictions where true;
  delete from public.matches where true;

  -- Whoever remains after the Edge Function removes non-admin accounts
  -- (i.e. the admin) starts from a clean slate too — points are a cache
  -- derived from predictions, which no longer exist.
  update public.players set points = 0 where true;

  -- Prize distribution is league-specific, not app-wide config.
  update public.settings
  set first_place_prize = 0,
      second_place_prize = 0,
      third_place_prize = 0,
      updated_at = now()
  where true;
end;
$$;

revoke all on function public.reset_league_data() from public;
grant execute on function public.reset_league_data() to authenticated;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0007_remove_default_payment_amount.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — remove the €20 default payment amount
-- ============================================================================
-- players.payment_amount (migration 0004) defaulted new rows to 20, so
-- every player created via the admin-create-player Edge Function silently
-- got €20 regardless of what they actually paid. The admin now enters the
-- real amount explicitly in the Add Player form; the Edge Function sets
-- payment_amount right after creating the account. This just removes the
-- old default so nothing falls back to 20 by accident — the "not null"
-- constraint still requires a value, so the default becomes 0 (a genuinely
-- neutral "nothing entered" value, and 0 is an explicitly allowed amount).
--
-- Existing players' payment_amount values are untouched — this only
-- changes what NEW rows get if a caller ever omits the column.
--
-- Idempotent / safe to re-run.
-- ============================================================================

alter table public.players
  alter column payment_amount set default 0;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0008_league_logo_and_player_management.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — admin-editable league logo + player mgmt
-- ============================================================================
-- Three independent pieces, all reusing the existing single-competition
-- structure (no new tables, no multi-league/membership model):
--
--   1. settings.logo_url — one nullable column on the existing settings
--      singleton row. NULL means "no custom logo, use the default
--      /tipovacka-logo.png"; non-null is a public Storage URL. A new
--      public, read-only RPC (get_league_logo_url) exposes just this one
--      column to EVERYONE, including logged-out visitors — settings' own
--      RLS (has_access()) intentionally still protects the prize columns,
--      but the logo has to be visible on the login screen too, before
--      anyone is authenticated at all.
--
--   2. A new `league-logo` Storage bucket, admin-write-only, holding a
--      single fixed object (`current-logo`) that every upload overwrites —
--      "replace" never orphans a file, "remove" deletes that one known
--      object.
--
--   3. Two admin-only SECURITY DEFINER RPCs for the Players management
--      panel:
--        - admin_get_player_email: auth.users.email isn't exposed by any
--          existing table/view; this reads it narrowly, admin-only.
--        - admin_delete_player: deletes ONLY the public.players row (never
--          auth.users) — predictions/chat_messages cascade via their
--          existing FK to players.id (migration 0001), exactly as
--          today. The person's login account is untouched; they simply no
--          longer have a player profile in this competition, which the
--          app already treats as "not logged in" (see
--          authService.fetchProfile).
--
-- Idempotent / safe to re-run.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. settings.logo_url
-- ----------------------------------------------------------------------------
alter table public.settings
  add column if not exists logo_url text;

grant update (logo_url) on public.settings to authenticated;

-- Public — deliberately bypasses settings' own has_access()-gated RLS.
-- Returns ONLY the logo URL, nothing else on the row (prize amounts stay
-- exactly as gated as before).
create or replace function public.get_league_logo_url()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select logo_url from public.settings where id = true;
$$;

grant execute on function public.get_league_logo_url() to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 2. league-logo Storage bucket — single shared object, admin-write-only
-- ----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'league-logo',
  'league-logo',
  true,
  5242880, -- 5 MB
  array['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/svg+xml']
)
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists league_logo_select on storage.objects;
create policy league_logo_select on storage.objects for select to authenticated
  using (bucket_id = 'league-logo');

drop policy if exists league_logo_admin_insert on storage.objects;
create policy league_logo_admin_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'league-logo'
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

drop policy if exists league_logo_admin_update on storage.objects;
create policy league_logo_admin_update on storage.objects for update to authenticated
  using (
    bucket_id = 'league-logo'
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  )
  with check (
    bucket_id = 'league-logo'
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

drop policy if exists league_logo_admin_delete on storage.objects;
create policy league_logo_admin_delete on storage.objects for delete to authenticated
  using (
    bucket_id = 'league-logo'
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

-- ----------------------------------------------------------------------------
-- 3. Player management RPCs (admin-only, re-checked independently of RLS —
-- same pattern as reset_league_data() in 0005)
-- ----------------------------------------------------------------------------
create or replace function public.admin_get_player_email(p_player_id uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_email text;
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže zobraziť email hráča.' using errcode = '42501';
  end if;

  select email into v_email from auth.users where id = p_player_id;
  return v_email;
end;
$$;

revoke all on function public.admin_get_player_email(uuid) from public;
grant execute on function public.admin_get_player_email(uuid) to authenticated;

create or replace function public.admin_delete_player(p_player_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže odstrániť hráča.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.players where id = p_player_id) then
    raise exception 'Hráč neexistuje.' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.players where id = p_player_id and is_admin) then
    raise exception 'Administrátorský účet nie je možné odstrániť.' using errcode = '42501';
  end if;

  -- Only the players row — predictions/chat_messages cascade via their
  -- existing FK to players.id. auth.users is never touched, so the
  -- person's account (and ability to log in elsewhere) is unaffected;
  -- they simply have no profile in this competition anymore.
  delete from public.players where id = p_player_id;
end;
$$;

revoke all on function public.admin_delete_player(uuid) from public;
grant execute on function public.admin_delete_player(uuid) to authenticated;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0009_predictions_visibility_before_kickoff.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — real, RLS-enforced prediction privacy
-- ============================================================================
-- predictions_select has never been time-scoped (migration 0001: `using
-- (true)`; migration 0004: `using (has_access())`) — any authenticated,
-- paying caller could always SELECT every player's prediction for every
-- match, including ones that haven't kicked off yet. "You can't see other
-- players' picks before kickoff" has only ever been a client-side
-- rendering convention (Live/History/Admin Matches all fetch the full
-- predictions table and just choose what to render) — never actually
-- enforced by Postgres.
--
-- This closes that gap for real, for EVERY caller (players and Admin
-- alike — no special-casing): you can always read your OWN prediction
-- (needed to see/edit "my tip" before a match starts), and you can read
-- ANYONE's prediction once their match has started or finished. This is
-- exactly the rule the rest of the app already assumes is true — Live only
-- ever renders LIVE matches, History only ever renders FINISHED ones, and
-- points (computePlayerStats) only ever count predictions with a non-null
-- `points`, which only exists after a match finishes — so nothing that
-- currently works starts receiving fewer rows than it already relied on.
--
-- Idempotent / safe to re-run.
-- ============================================================================

drop policy if exists predictions_select on public.predictions;
create policy predictions_select on public.predictions for select to authenticated
  using (
    player_id = auth.uid()
    or (
      public.has_access()
      and exists (
        select 1 from public.matches m
        where m.id = match_id and (m.finished or m.start_time <= now())
      )
    )
  );

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0010_prediction_completion_counter.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — prediction completion counter (aggregate only)
-- ============================================================================
-- Dashboard match cards show "3/13 players have submitted" — a pure
-- completion count, never who submitted or what they predicted. The
-- existing predictions_select policy (migration 0009) already blocks a
-- player from reading OTHER players' prediction rows before kickoff, so
-- the frontend genuinely cannot compute this count itself from already
-- -fetched data for an upcoming match — it has to come from a dedicated
-- aggregate RPC that returns counts only, never rows.
--
-- One SECURITY DEFINER function, callable by anyone with app access,
-- returning ONE row per non-finished match: `match_id`, `submitted_count`,
-- `total_players`. No player_id, no name, no predicted score — just two
-- numbers. `total_players` is "active" players — the same is_paid/is_admin
-- set that has_access() itself is built from, i.e. everyone who's actually
-- eligible to submit a prediction at all.
--
-- Idempotent / safe to re-run.
-- ============================================================================

create or replace function public.get_predictions_completion()
returns table (match_id uuid, submitted_count bigint, total_players bigint)
language sql
stable
security definer
set search_path = public
as $$
  select
    m.id as match_id,
    (
      select count(*)
      from public.predictions pr
      join public.players p on p.id = pr.player_id
      where pr.match_id = m.id and (p.is_paid or p.is_admin)
    ) as submitted_count,
    (select count(*) from public.players p where p.is_paid or p.is_admin) as total_players
  from public.matches m
  where m.finished = false and public.has_access();
$$;

grant execute on function public.get_predictions_completion() to authenticated;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0011_team_library.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — Team Library (predefined + custom teams)
-- ============================================================================
-- Reuses the existing public.teams table as-is (id/name/short_name/logo/
-- primary_color/secondary_color already there since migration 0001) rather
-- than creating a second table. Adds exactly one column to distinguish the
-- 36 already-seeded Champions League teams (is_custom = false, the
-- default — so every existing row is classified correctly with no backfill
-- needed) from teams an Admin creates through the app (is_custom = true).
--
-- teams currently has SELECT-only grants/RLS (writes were "seed/admin-SQL
-- only" per its own migration 0001 comment) — this adds real INSERT/UPDATE/
-- DELETE for admins, scoped so:
--   - Column grants cover exactly what the custom-team form needs: name,
--     short_name, logo, primary_color, secondary_color (already-existing
--     columns since migration 0001, used by TeamBadge's generated-crest
--     fallback for a team with no logo — nothing new added here).
--   - INSERT must self-declare is_custom = true — the app can never create
--     a "predefined" row.
--   - DELETE requires is_custom = true on the EXISTING row — a predefined
--     team can never be deleted, regardless of what the client sends.
--   - UPDATE is allowed on ANY row (predefined or custom) for logo/colors —
--     "change the badge of a default team" needs that — but a BEFORE
--     UPDATE trigger (enforce_predefined_team_identity, below) rejects any
--     attempt to change name/short_name/country/is_custom on a predefined
--     row specifically. A custom row has no such restriction. is_custom
--     itself is also simply not in the UPDATE column grant, so a custom
--     team can't be "promoted" to predefined either way.
--
-- Deleting a custom team still relies on the FK that already exists
-- (matches.home_team_id/away_team_id → teams.id, no ON DELETE clause —
-- i.e. RESTRICT): if any match references the team, Postgres itself
-- rejects the delete with a foreign_key_violation rather than the app
-- cascading anything. No new logic needed for that — it was already safe.
--
-- Also adds a `team-logos` Storage bucket (admin-write-only, public read —
-- same pattern as `league-logo` in migration 0008) for custom teams'
-- optional uploaded crest; predefined teams' logo column is untouched
-- (currently NULL for all 36 — they render via the generated SVG crest
-- fallback already built into TeamBadge.jsx).
--
-- Idempotent / safe to re-run. Does not modify or delete any existing row.
-- ============================================================================

alter table public.teams
  add column if not exists is_custom boolean not null default false;

grant insert (id, name, short_name, logo, is_custom, primary_color, secondary_color) on public.teams to authenticated;
grant update (name, short_name, logo, primary_color, secondary_color) on public.teams to authenticated;
grant delete on public.teams to authenticated;

drop policy if exists teams_admin_insert on public.teams;
create policy teams_admin_insert on public.teams for insert to authenticated
  with check (
    is_custom = true
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

-- Predefined teams' name/short_name/country/is_custom stay locked via the
-- trigger below, not via this policy — this policy itself just re-checks
-- admin status, same as everywhere else.
create or replace function public.enforce_predefined_team_identity()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not OLD.is_custom then
    if NEW.name is distinct from OLD.name
       or NEW.short_name is distinct from OLD.short_name
       or NEW.country is distinct from OLD.country
       or NEW.is_custom is distinct from OLD.is_custom then
      raise exception 'Predvolený tím je možné upraviť iba v logu a farbách.' using errcode = '42501';
    end if;
  end if;
  return NEW;
end;
$$;

drop trigger if exists trg_enforce_predefined_team_identity on public.teams;
create trigger trg_enforce_predefined_team_identity
  before update on public.teams
  for each row execute function public.enforce_predefined_team_identity();

drop policy if exists teams_admin_update on public.teams;
create policy teams_admin_update on public.teams for update to authenticated
  using (exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin))
  with check (exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin));

drop policy if exists teams_admin_delete on public.teams;
create policy teams_admin_delete on public.teams for delete to authenticated
  using (
    is_custom = true
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

-- ----------------------------------------------------------------------------
-- team-logos Storage bucket — one object per custom team, keyed by the
-- team's own id (a client-generated uuid, so it's known before upload).
-- ----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'team-logos',
  'team-logos',
  true,
  5242880, -- 5 MB
  array['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/svg+xml']
)
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists team_logos_select on storage.objects;
create policy team_logos_select on storage.objects for select to authenticated
  using (bucket_id = 'team-logos');

drop policy if exists team_logos_admin_insert on storage.objects;
create policy team_logos_admin_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'team-logos'
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

drop policy if exists team_logos_admin_update on storage.objects;
create policy team_logos_admin_update on storage.objects for update to authenticated
  using (
    bucket_id = 'team-logos'
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  )
  with check (
    bucket_id = 'team-logos'
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

drop policy if exists team_logos_admin_delete on storage.objects;
create policy team_logos_admin_delete on storage.objects for delete to authenticated
  using (
    bucket_id = 'team-logos'
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0012_result_correction_requests.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — Result Correction Requests
-- ============================================================================
-- Closes the one real gap in the existing "finished results are locked"
-- story: matches.finished/final_home_score/final_away_score were already
-- excluded from the direct UPDATE grant on `matches` (migration 0001) — no
-- client, admin included, could ever touch them with a plain update. But
-- finish_match() is SECURITY DEFINER, so it's exempt from that grant by
-- design, and its body had no guard against being called again on an
-- already-finished match. That was the actual backdoor: any admin could
-- silently re-finish a match at any time (exactly what the Dokončené tab's
-- "Update Result" button — now removed — relied on).
--
-- This migration:
--   1. Factors finish_match()'s "apply score + recalc predictions + recalc
--      players" body out into apply_match_result() — a private helper
--      (no grant to authenticated; only reachable from inside another
--      SECURITY DEFINER function, which runs as the owner regardless of
--      grants). Both finish_match() and an approved correction call this
--      SAME function — there is exactly one scoring code path.
--   2. Replaces finish_match() with a version that rejects outright if the
--      match is already finished. This alone makes every existing
--      finished match locked immediately on deploy — finished already
--      meant "has a result"; this migration is what makes it also mean
--      "can't be silently changed". No data is touched, no backfill, no
--      new column needed for "locked" — finished IS the lock.
--   3. Adds the only legal way to change a finished result: a request +
--      unanimous-vote workflow, in two new tables. Both are append-only in
--      practice (nothing is ever deleted or overwritten by the app) — that
--      makes them the permanent audit trail on their own; no separate
--      history table needed.
--
-- Idempotent / safe to re-run. Does not modify or delete any existing row.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. result_correction_requests — one row per correction request.
-- ----------------------------------------------------------------------------
create table if not exists public.result_correction_requests (
  id                uuid primary key default gen_random_uuid(),
  match_id          uuid not null references public.matches (id),
  requested_by      uuid not null references public.players (id),
  old_home_score    smallint not null,
  old_away_score    smallint not null,
  new_home_score    smallint not null,
  new_away_score    smallint not null,
  reason            text not null,
  status            text not null default 'pending',
  created_at        timestamptz not null default now(),
  resolved_at       timestamptz,
  constraint result_correction_requests_status_valid check (status in ('pending', 'approved', 'rejected')),
  constraint result_correction_requests_scores_non_negative check (
    old_home_score >= 0 and old_away_score >= 0 and new_home_score >= 0 and new_away_score >= 0
  ),
  constraint result_correction_requests_scores_differ check (
    old_home_score <> new_home_score or old_away_score <> new_away_score
  ),
  constraint result_correction_requests_reason_present check (length(trim(reason)) > 0)
);

-- The real guard against two simultaneous pending requests for the same
-- match — a partial unique index, not just a friendly pre-check in the
-- RPC. Multiple RESOLVED requests for the same match over time are fine
-- and expected (that's the audit history); only concurrent PENDING ones
-- are blocked.
create unique index if not exists result_correction_requests_one_pending_per_match
  on public.result_correction_requests (match_id)
  where status = 'pending';

create index if not exists idx_result_correction_requests_match_id
  on public.result_correction_requests (match_id);

-- ----------------------------------------------------------------------------
-- 2. result_correction_votes — one row per (request, eligible voter),
-- pre-populated at request-creation time. This single table is
-- simultaneously the eligibility snapshot (a row existing at all = was
-- eligible when the request was created), the live vote record (vote is
-- null until cast), and the audit trail of who voted what and when.
-- ----------------------------------------------------------------------------
create table if not exists public.result_correction_votes (
  id          uuid primary key default gen_random_uuid(),
  request_id  uuid not null references public.result_correction_requests (id),
  player_id   uuid not null references public.players (id),
  vote        boolean, -- null = not yet voted, true = agree, false = disagree
  voted_at    timestamptz,
  unique (request_id, player_id)
);

create index if not exists idx_result_correction_votes_request_id
  on public.result_correction_votes (request_id);

-- ----------------------------------------------------------------------------
-- 3. RLS — read is open to anyone with app access (the whole point of a
-- democratic process is that it's visible), writes are RPC-only. No
-- INSERT/UPDATE/DELETE grant is given to `authenticated` on either table —
-- exactly the same pattern matches.finished already relies on — so a
-- client calling these tables directly is rejected at the grant level,
-- before RLS is even evaluated.
-- ----------------------------------------------------------------------------
alter table public.result_correction_requests enable row level security;
alter table public.result_correction_votes enable row level security;

drop policy if exists result_correction_requests_select on public.result_correction_requests;
create policy result_correction_requests_select on public.result_correction_requests for select to authenticated
  using (public.has_access());

drop policy if exists result_correction_votes_select on public.result_correction_votes;
create policy result_correction_votes_select on public.result_correction_votes for select to authenticated
  using (public.has_access());

grant select on public.result_correction_requests to authenticated;
grant select on public.result_correction_votes to authenticated;

-- ----------------------------------------------------------------------------
-- 4. apply_match_result — private helper, not exposed to `authenticated`
-- at all. The one place a result is ever written and points ever
-- recalculated, called from finish_match() (first close) and from
-- vote_on_result_correction() (an approved correction) — never a second,
-- separate implementation of scoring.
-- ----------------------------------------------------------------------------
create or replace function public.apply_match_result(
  p_match_id uuid,
  p_final_home_score smallint,
  p_final_away_score smallint
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.matches
  set finished = true,
      final_home_score = p_final_home_score,
      final_away_score = p_final_away_score
  where id = p_match_id;

  -- Same bypass finish_match()/recalculate_all_points() already used before
  -- this logic was factored out into this function (see migration 0002) —
  -- without it, enforce_prediction_change_limit() mistakes this system
  -- recalculation for a player's own (already-exhausted) manual save and
  -- rejects it. `true` as the third argument scopes it to the current
  -- transaction only, exactly as before — it can never leak into or affect
  -- a player's own subsequent prediction save in a separate request.
  perform set_config('app.bypass_prediction_limit', 'true', true);

  update public.predictions
  set points = public.calculate_points(
        predicted_home_score, predicted_away_score, p_final_home_score, p_final_away_score
      ),
      updated_at = now()
  where match_id = p_match_id;

  update public.players pl
  set points = coalesce((
    select sum(pr.points) from public.predictions pr
    where pr.player_id = pl.id and pr.points is not null
  ), 0)
  where pl.id in (select player_id from public.predictions where match_id = p_match_id);
end;
$$;

revoke all on function public.apply_match_result(uuid, smallint, smallint) from public;
-- Deliberately no grant to authenticated — only reachable from inside
-- another SECURITY DEFINER function (which runs as the owner regardless
-- of the caller's own grants), never directly.

-- ----------------------------------------------------------------------------
-- 5. finish_match — same signature, same admin re-check as before, but now
-- rejects outright if the match is already finished. This is the actual
-- fix: it closes the backdoor that let an admin silently re-finish an
-- already-finished match, which is what "locks" every match (existing and
-- future) the moment this migration is applied.
-- ----------------------------------------------------------------------------
create or replace function public.finish_match(
  p_match_id uuid,
  p_final_home_score smallint,
  p_final_away_score smallint
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_finished boolean;
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže ukončiť zápas.' using errcode = '42501';
  end if;

  if p_final_home_score is null or p_final_away_score is null
     or p_final_home_score < 0 or p_final_away_score < 0 then
    raise exception 'Neplatný výsledok zápasu.' using errcode = '22023';
  end if;

  select finished into v_finished from public.matches where id = p_match_id for update;

  if v_finished is null then
    raise exception 'Zápas sa nenašiel.' using errcode = 'P0002';
  end if;

  if v_finished then
    raise exception 'Zápas je už ukončený a uzamknutý. Na zmenu výsledku použi žiadosť o opravu.' using errcode = '42501';
  end if;

  perform public.apply_match_result(p_match_id, p_final_home_score, p_final_away_score);
end;
$$;
-- Grant unchanged from migration 0001 (same function signature, CREATE OR
-- REPLACE preserves it): grant execute on finish_match(...) to authenticated.

-- ----------------------------------------------------------------------------
-- 6. request_result_correction — admin-only entry point. Snapshots the
-- eligible-voter set (has_access(), excluding the requester) atomically in
-- the same transaction as the request itself, so no concurrent membership
-- change can affect who's eligible for THIS request.
-- ----------------------------------------------------------------------------
create or replace function public.request_result_correction(
  p_match_id uuid,
  p_new_home_score smallint,
  p_new_away_score smallint,
  p_reason text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_match record;
  v_request_id uuid;
  v_reason text;
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže požiadať o opravu výsledku.' using errcode = '42501';
  end if;

  -- Locks the match row so a concurrent finish/correction can't race this
  -- request's "old score" snapshot.
  select id, finished, final_home_score, final_away_score
    into v_match
    from public.matches
    where id = p_match_id
    for update;

  if v_match.id is null then
    raise exception 'Zápas sa nenašiel.' using errcode = 'P0002';
  end if;

  if not v_match.finished then
    raise exception 'Zápas ešte nie je ukončený.' using errcode = '22023';
  end if;

  if p_new_home_score is null or p_new_away_score is null
     or p_new_home_score < 0 or p_new_away_score < 0 then
    raise exception 'Neplatný výsledok zápasu.' using errcode = '22023';
  end if;

  if p_new_home_score = v_match.final_home_score and p_new_away_score = v_match.final_away_score then
    raise exception 'Nový výsledok je rovnaký ako súčasný.' using errcode = '22023';
  end if;

  v_reason := trim(coalesce(p_reason, ''));
  if v_reason = '' then
    raise exception 'Uveď dôvod opravy.' using errcode = '22023';
  end if;

  -- Fast, friendly failure before ever touching the table — the partial
  -- unique index above is the real backstop against a race between two
  -- simultaneous requests, same "pre-check + real constraint" pattern
  -- already used elsewhere in this schema (e.g. duplicate player names).
  if exists (select 1 from public.result_correction_requests where match_id = p_match_id and status = 'pending') then
    raise exception 'Pre tento zápas už existuje čakajúca žiadosť o opravu.' using errcode = '23505';
  end if;

  insert into public.result_correction_requests (
    match_id, requested_by, old_home_score, old_away_score, new_home_score, new_away_score, reason
  ) values (
    p_match_id, auth.uid(), v_match.final_home_score, v_match.final_away_score,
    p_new_home_score, p_new_away_score, v_reason
  )
  returning id into v_request_id;

  insert into public.result_correction_votes (request_id, player_id)
  select v_request_id, p.id
  from public.players p
  where (p.is_paid or p.is_admin) and p.id <> auth.uid();

  return v_request_id;
end;
$$;

revoke all on function public.request_result_correction(uuid, smallint, smallint, text) from public;
grant execute on function public.request_result_correction(uuid, smallint, smallint, text) to authenticated;

-- ----------------------------------------------------------------------------
-- 7. vote_on_result_correction — the only way a vote (or the resulting
-- approval/rejection, or the score change itself) is ever written.
--
-- The `for update` lock on the request row is what makes unanimous-
-- approval detection race-safe: if the last two required voters vote at
-- the same instant, the second call's lock acquisition blocks until the
-- first call's transaction (vote write + approval check + apply, if it
-- was the final vote) has fully committed — so the second call always
-- sees an up-to-date, consistent vote count, never a stale one that could
-- leave a fully-approved request stuck un-applied.
-- ----------------------------------------------------------------------------
create or replace function public.vote_on_result_correction(
  p_request_id uuid,
  p_approve boolean
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request record;
  v_seat record;
  v_all_approved boolean;
begin
  select id, match_id, status, new_home_score, new_away_score
    into v_request
    from public.result_correction_requests
    where id = p_request_id
    for update;

  if v_request.id is null then
    raise exception 'Žiadosť o opravu sa nenašla.' using errcode = 'P0002';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'O tejto žiadosti sa už rozhodlo.' using errcode = '22023';
  end if;

  select id, vote into v_seat
    from public.result_correction_votes
    where request_id = p_request_id and player_id = auth.uid()
    for update;

  if v_seat.id is null then
    raise exception 'Nemáš právo hlasovať o tejto žiadosti.' using errcode = '42501';
  end if;

  if v_seat.vote is not null then
    raise exception 'O tejto žiadosti si už hlasoval.' using errcode = '22023';
  end if;

  update public.result_correction_votes
  set vote = p_approve, voted_at = now()
  where id = v_seat.id;

  if not p_approve then
    -- First rejection wins immediately — not a wait-for-everyone model.
    update public.result_correction_requests
    set status = 'rejected', resolved_at = now()
    where id = p_request_id;
    return;
  end if;

  select not exists (
    select 1 from public.result_correction_votes
    where request_id = p_request_id and (vote is distinct from true)
  ) into v_all_approved;

  if v_all_approved then
    update public.result_correction_requests
    set status = 'approved', resolved_at = now()
    where id = p_request_id;

    perform public.apply_match_result(v_request.match_id, v_request.new_home_score, v_request.new_away_score);
  end if;
end;
$$;

revoke all on function public.vote_on_result_correction(uuid, boolean) from public;
grant execute on function public.vote_on_result_correction(uuid, boolean) to authenticated;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0013_apply_match_result_bypass_fix.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — apply_match_result() bypass fix
-- ============================================================================
-- migration 0012 (already deployed to production) factored finish_match()'s
-- "apply score + recalc predictions + recalc players" body out into
-- apply_match_result() — but dropped the one thing that made that bulk
-- predictions.points update safe: the transaction-local bypass flag
-- finish_match()/recalculate_all_points() have set before it since
-- migration 0002. Without it, enforce_prediction_change_limit() (still
-- exactly as migration 0002 left it — untouched here) sees the system's
-- own score recalculation as if it were a player's own manual save, and
-- rejects it once that player has already used both saves on that match
-- (save_count = 2) — a normal, common state for any real finished match.
--
-- This migration does exactly one thing: CREATE OR REPLACE
-- public.apply_match_result(...) with that single missing line restored,
-- immediately before the predictions update it protects. The base for
-- this was the CURRENT production definition of the function, read
-- directly via pg_get_functiondef() before writing this file — every
-- other line is byte-for-byte identical to what's live today. Nothing
-- else — no other function, table, trigger, RLS policy, or column — is
-- touched, and no existing row is read or written by this migration
-- (CREATE OR REPLACE FUNCTION only redefines the function itself).
--
-- Idempotent / safe to re-run.
-- ============================================================================

create or replace function public.apply_match_result(
  p_match_id uuid,
  p_final_home_score smallint,
  p_final_away_score smallint
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.matches
  set finished = true,
      final_home_score = p_final_home_score,
      final_away_score = p_final_away_score
  where id = p_match_id;

  -- Same bypass finish_match()/recalculate_all_points() already use (see
  -- migration 0002) — without it, enforce_prediction_change_limit()
  -- mistakes this system recalculation for a player's own (already-
  -- exhausted) manual save and rejects it. `true` as the third argument
  -- scopes it to the current transaction only, exactly as before — it
  -- can never leak into or affect a player's own subsequent prediction
  -- save in a separate request.
  perform set_config('app.bypass_prediction_limit', 'true', true);

  update public.predictions
  set points = public.calculate_points(
        predicted_home_score, predicted_away_score, p_final_home_score, p_final_away_score
      ),
      updated_at = now()
  where match_id = p_match_id;

  update public.players pl
  set points = coalesce((
    select sum(pr.points) from public.predictions pr
    where pr.player_id = pl.id and pr.points is not null
  ), 0)
  where pl.id in (select player_id from public.predictions where match_id = p_match_id);
end;
$$;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0014_league_announcements.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — league announcements
-- ============================================================================
-- This app is a single competition — no `leagues` table exists (same
-- architecture decision already made for the Team Library / league logo
-- features) — so "the league" an announcement belongs to is simply this
-- whole app; no league_id column is needed. Reuses `players`/`has_access()`
-- exactly like every other feature.
--
-- Two tables:
--   - league_announcements: one row per PUBLISH. Editing the admin form
--     and republishing is a NEW row (a new id), never an UPDATE to an
--     existing one — that's what gives every republish a fresh identity
--     members who already acknowledged the previous version still need to
--     see. "Current" (order by created_at desc limit 1) is simply the
--     latest row; there is no separate draft/unpublished state to protect
--     since a row only ever exists once actually published.
--   - league_announcement_reads: one row per (announcement, player) once
--     they've acknowledged it. No RPC needed for either table — both are
--     simple, single-row, ownership-scoped inserts, fully expressible with
--     plain RLS (same pattern as matches_admin_insert / chat_insert_own),
--     unlike the correction-request workflow's multi-step, transactional
--     approval logic.
--
-- Idempotent / safe to re-run. Does not modify or delete any existing row.
-- ============================================================================

create table if not exists public.league_announcements (
  id          uuid primary key default gen_random_uuid(),
  title       text not null,
  message     text not null,
  created_at  timestamptz not null default now(),
  created_by  uuid not null references public.players (id),
  constraint league_announcements_title_present check (length(trim(title)) > 0),
  constraint league_announcements_message_present check (length(trim(message)) > 0)
);

create index if not exists idx_league_announcements_created_at
  on public.league_announcements (created_at desc);

create table if not exists public.league_announcement_reads (
  announcement_id  uuid not null references public.league_announcements (id),
  player_id        uuid not null references public.players (id),
  acknowledged_at  timestamptz not null default now(),
  primary key (announcement_id, player_id)
);

-- ----------------------------------------------------------------------------
-- RLS — read is has_access()-gated (same as everything else); writes are
-- narrowly scoped: only an admin can create an announcement (and only ever
-- under their own id), only a player can acknowledge on their own behalf.
-- Nothing here is ever updated or deleted by the app.
-- ----------------------------------------------------------------------------
alter table public.league_announcements enable row level security;
alter table public.league_announcement_reads enable row level security;

drop policy if exists league_announcements_select on public.league_announcements;
create policy league_announcements_select on public.league_announcements for select to authenticated
  using (public.has_access());

drop policy if exists league_announcements_admin_insert on public.league_announcements;
create policy league_announcements_admin_insert on public.league_announcements for insert to authenticated
  with check (
    created_by = auth.uid()
    and exists (select 1 from public.players p where p.id = auth.uid() and p.is_admin)
  );

grant select on public.league_announcements to authenticated;
grant insert (title, message, created_by) on public.league_announcements to authenticated;

drop policy if exists league_announcement_reads_select on public.league_announcement_reads;
create policy league_announcement_reads_select on public.league_announcement_reads for select to authenticated
  using (player_id = auth.uid());

drop policy if exists league_announcement_reads_insert_own on public.league_announcement_reads;
create policy league_announcement_reads_insert_own on public.league_announcement_reads for insert to authenticated
  with check (
    player_id = auth.uid()
    and public.has_access()
  );

grant select on public.league_announcement_reads to authenticated;
grant insert (announcement_id, player_id) on public.league_announcement_reads to authenticated;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0015_clear_engagement_data_before_reset.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — reset-league regression fix
-- ============================================================================
-- Result Correction (migration 0012) and League Announcements (migration
-- 0014) both added tables referencing players with ON DELETE NO ACTION —
-- deliberately: it stops a single, targeted admin_delete_player() call
-- from removing an inconvenient voter to manipulate a pending correction.
-- That protection is correct for THAT action, but it also unintentionally
-- blocks admin-reset-league's non-admin auth-user deletion (auth.users →
-- players cascades, but that cascade fails wherever these NO ACTION FKs
-- still point at the row being removed), since a full league reset is a
-- fundamentally different, all-encompassing operation.
--
-- Fix: one new function that explicitly clears exactly these four tables
-- — children before parents, same "explicit and auditable rather than
-- relied-upon-implicitly" philosophy reset_league_data() itself already
-- documents — called by admin-reset-league BEFORE it attempts to delete
-- any non-admin auth user. reset_league_data() itself is NOT modified —
-- it still only ever runs after every player deletion has already
-- succeeded, preserving that existing safest-failure-mode ordering for
-- matches/predictions/chat/points. admin_delete_player() and every
-- existing FK/RLS definition are untouched.
--
-- Idempotent / safe to re-run. Does not modify or delete any existing row
-- at migration-apply time — this only defines a function; it deletes
-- nothing until explicitly called later, by the reset flow itself.
-- ============================================================================

create or replace function public.clear_result_correction_and_announcement_data()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže resetovať ligu.' using errcode = '42501';
  end if;

  -- Children before parents: result_correction_votes.request_id and
  -- league_announcement_reads.announcement_id are themselves ON DELETE NO
  -- ACTION against their own parent table, so deleting requests/
  -- announcements first would fail the same way player deletion does.
  -- `where true` is required by Supabase's `safeupdate` extension, which
  -- rejects a bare DELETE with no WHERE clause; it does not change which
  -- rows are affected.
  delete from public.result_correction_votes where true;
  delete from public.result_correction_requests where true;
  delete from public.league_announcement_reads where true;
  delete from public.league_announcements where true;
end;
$$;

revoke all on function public.clear_result_correction_and_announcement_data() from public;
grant execute on function public.clear_result_correction_and_announcement_data() to authenticated;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0016_admin_delete_player_engagement_cleanup.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — admin_delete_player engagement cleanup
-- ============================================================================
-- Result Correction (migration 0012) and League Announcements (migration
-- 0014) both added tables referencing players with ON DELETE NO ACTION —
-- deliberately, to stop a targeted admin_delete_player() call from removing
-- an inconvenient voter mid-vote. Migration 0015 cleared these tables
-- WHOLESALE, but only ahead of a full league reset — that's correct for a
-- reset (everything is being wiped anyway) but wrong here: a single player
-- deletion must never touch another player's rows.
--
-- Root cause of the "Igrača nije moguće obrisati." failure: any player who
-- has ever cast a correction vote, acknowledged an announcement, requested
-- a correction, or created an announcement still has a row in one of these
-- four tables, and admin_delete_player()'s plain `delete from
-- public.players` has no cleanup step for them at all — Postgres rejects
-- the delete outright (23503, result_correction_votes_player_id_fkey,
-- reproduced against production in a rolled-back transaction).
--
-- This migration replaces admin_delete_player() only. It does not touch
-- reset_league_data(), clear_result_correction_and_announcement_data(), or
-- any FK's ON DELETE behavior — those stay exactly as migrations 0012,
-- 0014 and 0015 left them.
--
-- New behavior, in order:
--   1. Block deletion outright if the player is the requester of, or an
--      eligible voter (voted or not — see below) on, a still-PENDING
--      correction request. "Pending" is the literal status value used
--      throughout 0012 (result_correction_requests.status, default
--      'pending', check constraint ('pending','approved','rejected'),
--      the partial unique index that allows only one pending request per
--      match). This is the one case a scoped cleanup cannot safely paper
--      over: deleting a required voter mid-vote would either silently
--      erase their cast vote or leave the process permanently unable to
--      reach unanimity (a vacated eligibility slot is never re-added).
--   2. Otherwise, delete ONLY that player's own rows from the four
--      engagement tables — never another player's — then delete the
--      players row itself. Everything here is one function call, hence
--      one implicit transaction: any failure mid-way rolls back the
--      entire operation automatically, including the final player delete.
--
-- Two of those four tables need a second step beyond "delete this
-- player's own rows", because they are themselves referenced by other
-- NO ACTION children (see 0015's own comment on this):
--   - Deleting a RESOLVED correction request this player created would
--     violate result_correction_votes.request_id unless every voter's
--     row on that specific request is removed first. Rule 1 above already
--     guarantees the request is resolved (not pending) before this runs,
--     so those votes are dead history for a decision that's already been
--     made — removing them removes the play-by-play of settled votes on
--     this one request, not any player's participation in anything still
--     active. See "Edge cases" in the follow-up report for the deliberate
--     scope of this.
--   - Symmetrically, deleting an announcement this player created would
--     violate league_announcement_reads.announcement_id unless every
--     other reader's acknowledgment of that announcement is removed
--     first. In practice this table is currently unreachable in
--     production (league_announcements_admin_insert only lets an is_admin
--     player insert, and admin_delete_player() already refuses to delete
--     an admin), but is handled here defensively in case a player is ever
--     demoted from admin after creating one.
--
-- Idempotent / safe to re-run (create or replace). Does not modify or
-- delete any existing row at migration-apply time — this only redefines a
-- function; nothing runs until it's next called.
-- ============================================================================

create or replace function public.admin_delete_player(p_player_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.players where id = auth.uid() and is_admin) then
    raise exception 'Iba administrátor môže odstrániť hráča.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.players where id = p_player_id) then
    raise exception 'Hráč neexistuje.' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.players where id = p_player_id and is_admin) then
    raise exception 'Administrátorský účet nie je možné odstrániť.' using errcode = '42501';
  end if;

  -- Rule 1/2: block outright while the player is the requester of, or an
  -- eligible voter (cast or not — result_correction_votes rows are the
  -- eligibility snapshot itself, see 0012) on, any still-pending
  -- correction request. Scoped cleanup only ever proceeds once this is
  -- false, i.e. every request this player is involved in is resolved.
  if exists (
    select 1 from public.result_correction_requests
    where requested_by = p_player_id and status = 'pending'
  ) or exists (
    select 1
    from public.result_correction_votes v
    join public.result_correction_requests r on r.id = v.request_id
    where v.player_id = p_player_id and r.status = 'pending'
  ) then
    raise exception 'Hráča nie je možné odstrániť, kým prebieha oprava výsledku, ktorej sa týka.' using errcode = '22023';
  end if;

  -- This player's own votes on anyone's (resolved) requests.
  delete from public.result_correction_votes where player_id = p_player_id;

  -- Every voter's row on requests THIS player created — required before
  -- those requests can be deleted below (result_correction_votes.request_id
  -- is itself ON DELETE NO ACTION against result_correction_requests). Rule
  -- 1 above already guarantees every such request is resolved, not pending.
  delete from public.result_correction_votes
  where request_id in (
    select id from public.result_correction_requests where requested_by = p_player_id
  );

  delete from public.result_correction_requests where requested_by = p_player_id;

  -- This player's own acknowledgments of anyone's announcements.
  delete from public.league_announcement_reads where player_id = p_player_id;

  -- Every reader's acknowledgment of announcements THIS player created —
  -- required before those announcements can be deleted below
  -- (league_announcement_reads.announcement_id is itself ON DELETE NO
  -- ACTION against league_announcements). Currently unreachable in
  -- practice (only admins can create announcements, and admins can't be
  -- deleted), kept for correctness if that ever changes.
  delete from public.league_announcement_reads
  where announcement_id in (
    select id from public.league_announcements where created_by = p_player_id
  );

  delete from public.league_announcements where created_by = p_player_id;

  -- predictions/chat_messages cascade via their existing FK to players.id.
  -- auth.users is never touched, so the person's account (and ability to
  -- log in elsewhere) is unaffected; they simply have no profile in this
  -- competition anymore.
  delete from public.players where id = p_player_id;
end;
$$;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0017_bootstrap_first_admin.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 — first-admin bootstrap for fresh installs
-- ============================================================================
-- players.is_admin can only ever be set at signup, from
-- raw_user_meta_data->>'is_admin' (handle_new_user(), migration 0001) — no
-- client write grant exists for it afterward (see 0001's own comment on
-- this, line ~296). That's correct for the running app, but it means a
-- brand-new installation has no admin at all until someone with direct
-- database access (the SQL Editor) sets one.
--
-- Previously that meant hand-copying a UUID from Authentication > Users and
-- running a raw `update players set is_admin = true where id = '<uuid>'`.
-- This function replaces that with something safer and easier for a
-- non-technical customer:
--   - looked up by EMAIL, not UUID — the customer just types the address
--     they signed up with.
--   - only works while NO admin exists yet — once the very first admin is
--     set, every later call fails outright, so this can never be reused as
--     a standing privilege-escalation path.
--   - SECURITY DEFINER, but deliberately granted to nobody (`revoke all
--     from public`, no grant to authenticated/anon) — reachable only from
--     a connection with owner/superuser-equivalent privileges, i.e. the
--     Supabase SQL Editor, exactly like running any other raw SQL there
--     already is. The application's own API surface can never call it.
--
-- Idempotent / safe to re-run. Does not modify or delete any existing row
-- at migration-apply time — this only defines a function.
-- ============================================================================

create or replace function public.bootstrap_first_admin(p_email text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
begin
  if exists (select 1 from public.players where is_admin) then
    raise exception 'Administrátor už existuje. Túto funkciu je možné použiť iba pri prvej inštalácii.' using errcode = '42501';
  end if;

  select id into v_user_id from auth.users where email = p_email;
  if v_user_id is null then
    raise exception 'Používateľ s týmto emailom neexistuje. Najprv ho vytvor v Supabase Dashboard (Authentication > Users).' using errcode = 'P0002';
  end if;

  if not exists (select 1 from public.players where id = v_user_id) then
    raise exception 'Pre tohto používateľa ešte neexistuje profil hráča. Skús to znova o chvíľu.' using errcode = 'P0002';
  end if;

  update public.players set is_admin = true where id = v_user_id;
end;
$$;

revoke all on function public.bootstrap_first_admin(text) from public;

-- ============================================================================
-- SOURCE FILE: supabase/migrations/0018_payment_iban_settings.sql
-- ============================================================================
-- ============================================================================
-- TIPOVAČKA LIGA MAJSTROV 2026 (PickMates) — payment IBAN setting
-- ============================================================================
-- New Admin "Platba" section: the admin sets one IBAN that unpaid players
-- see on the existing access-blocked screen. Reuses the existing `settings`
-- singleton table (migration 0004) rather than a new table — same pattern
-- already used for `logo_url` (migration 0008): one nullable column, plus a
-- narrow public accessor RPC.
--
-- Why a dedicated RPC instead of loosening settings' own SELECT policy
-- (`has_access()`, migration 0004): an unpaid player is exactly the
-- audience that needs to read this value, and has_access() is false for
-- them by definition — that's the one existing policy this feature cannot
-- go through. get_payment_iban() mirrors get_league_logo_url() exactly:
-- SECURITY DEFINER, reads only this one column, and is the ONLY new way to
-- reach the settings row without has_access(). Unlike the logo function
-- this is granted to `authenticated` only, not `anon` — the IBAN is only
-- ever shown after login (on the blocked screen), never on the pre-login
-- screen the logo needs to reach.
--
-- settings' own SELECT/UPDATE RLS policies (migration 0004) are untouched:
-- has_access() still gates the raw table read exactly as before, and the
-- existing admin-only UPDATE policy already covers this new column with no
-- change needed — it already applies to the whole row regardless of which
-- columns are in a given UPDATE's SET list.
--
-- Idempotent / safe to re-run. Does not modify or delete any existing row.
-- ============================================================================

alter table public.settings add column if not exists payment_iban text;

grant update (payment_iban) on public.settings to authenticated;

create or replace function public.get_payment_iban()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select payment_iban from public.settings where id = true;
$$;

grant execute on function public.get_payment_iban() to authenticated;

